import React, { useState } from 'react';

import { DownloadDataButton } from './DownloadDataButton.js';
import { ChartToolbarRenderer } from '../../../core/components/toolbar/ChartToolbarRenderer.js';
import { useToolbarConfig } from '../../context/ToolbarContext.js';
import { useOverlayState } from '../../hooks/store/selectors.js';
import { zIndicesPieAreas } from '../../types/default.js';

const defaultToolbarPlacement = 'top-right';

const initialState = [
  {
    download: 0,
  },
];

export const PieChartToolbar = () => {
  const [isTooltipHidden, setIsTooltipHidden] = useState(false);
  const toolbarConfig = useToolbarConfig();
  const toolbarPlacement = toolbarConfig?.placement ?? defaultToolbarPlacement;
  const { mouseInBounds } = useOverlayState();

  return (
    <ChartToolbarRenderer
      visible={mouseInBounds}
      placement={toolbarPlacement}
      collapsed={toolbarConfig?.collapsed}
      draggable={toolbarConfig?.draggable}
      zIndex={zIndicesPieAreas.toolbar}
      initialA11yState={initialState}
      onToggleToolbar={setIsTooltipHidden}
    >
      {toolbarConfig?.downloadData?.enabled && (
        <DownloadDataButton hideTooltip={isTooltipHidden} />
      )}
    </ChartToolbarRenderer>
  );
};
